// Ejemplo: cargar opciones desde API
const res = await apiService.get('/api/prioridades');
return {
  selectOptions: { prioridad: res.data.map(d => ({ label: d.nombre, value: d.id })) },
  initialValues: { prioridad: '' }
};

// Visibilidad
if (modalFormData.tipo !== 'usuarios') return false;
// Carga paginada (opcional)
if (loadPass) {
  const res = await apiService.post('/users/search', { filter: [], limit: kaceSelectPageSize, offset: (kaceSelectPage - 1) * kaceSelectPageSize });
  const items = (res?.data?.data?.items ?? []).map(u => ({ label: u.nombres, value: u.id }));
  setSelectOptions('user', items, { append: kaceSelectPage > 1 });
  return true;
}
return true;

// Ejemplo: solo grupos permitidos ven acciones masivas
const id = getCurrentGroupId();
const allowed = ['REPLACE_WITH_GROUP_UUID'];
if (!id || !allowed.includes(String(id))) {
  return { bulkActions: [], disableBulkActions: true };
}
return { bulkActions: baseBulkActions, disableBulkActions: false };
